import Block from '../../../components/ui/Block';
import { motion } from 'framer-motion';

const Overview: React.FC = () => {
    return (
        <div className="space-y-8 pb-12 text-right" dir="rtl">
            <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                className="mb-8 border-b border-slate-200 dark:border-slate-800 pb-6"
            >
                <h1 className="text-4xl font-extrabold mb-4 bg-clip-text text-transparent bg-gradient-to-l from-emerald-500 to-teal-600">
                    ברוכים הבאים לעורך
                </h1>
                <p className="text-xl text-slate-600 dark:text-slate-300">
                    בחר שיעור מהתפריט בצד שמאל כדי להתחיל לערוך, או השתמש בסרגל הכלים בצד ימין להוספת רכיבים.
                </p>
            </motion.div>

            <Block type="info" title="איך מתחילים?">
                <p>
                    1. פתח את תוכן העניינים משמאל.<br/>
                    2. בחר שיעור.<br/>
                    3. השתמש בכפתור הפלוס מימין להוספת תבניות מוכנות.
                </p>
            </Block>
        </div>
    );
};

export default Overview;
